import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.yJK3qstQ.js";const h=JSON.parse('{"title":"Say It Out Loud: Spoken Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),n={name:"14-say-it-out-loud.md"};function s(r,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="say-it-out-loud-spoken-interview-scripts" tabindex="-1">Say It Out Loud: Spoken Interview Scripts <a class="header-anchor" href="#say-it-out-loud-spoken-interview-scripts" aria-label="Permalink to &quot;Say It Out Loud: Spoken Interview Scripts&quot;">​</a></h1><h2 id="project-pitch-60-seconds" tabindex="-1">Project Pitch (60 Seconds) <a class="header-anchor" href="#project-pitch-60-seconds" aria-label="Permalink to &quot;Project Pitch (60 Seconds)&quot;">​</a></h2><blockquote><p>&quot;I built the Gesture PDF Presenter, an interactive touchless presentation system powered by MediaPipe computer vision, React 18, and PDF.js. Using a standard laptop webcam, it tracks 21 hand landmarks in real time to let speakers advance slides, zoom into diagrams, and activate a virtual laser pointer using natural hand gestures in mid-air—eliminating the need for handheld clickers or touching a keyboard.&quot;</p></blockquote><h2 id="feature-scripts" tabindex="-1">Feature Scripts <a class="header-anchor" href="#feature-scripts" aria-label="Permalink to &quot;Feature Scripts&quot;">​</a></h2><h3 id="f1-mediapipe-21-landmark-tracking-pipeline" tabindex="-1">F1: MediaPipe 21-Landmark Tracking Pipeline <a class="header-anchor" href="#f1-mediapipe-21-landmark-tracking-pipeline" aria-label="Permalink to &quot;F1: MediaPipe 21-Landmark Tracking Pipeline&quot;">​</a></h3><blockquote><p>&quot;I built the tracking pipeline using Google&#39;s MediaPipe Hands in <code>GestureControl.tsx</code>. The webcam captures video at 30 frames per second, passing each frame to MediaPipe&#39;s WebAssembly model. It outputs 21 normalized three-dimensional landmarks corresponding to every knuckle and joint in the hand with sub-15 millisecond latency, providing the mathematical coordinates needed for touchless gesture detection.&quot;</p></blockquote><h3 id="f2-touchless-slide-navigation" tabindex="-1">F2: Touchless Slide Navigation <a class="header-anchor" href="#f2-touchless-slide-navigation" aria-label="Permalink to &quot;F2: Touchless Slide Navigation&quot;">​</a></h3><blockquote><p>&quot;To advance slides reliably, in <code>services/gestures.ts</code> I engineered a directional velocity algorithm. A common issue with computer vision presentations is accidental slide changes when a speaker moves their hands while speaking. My engine tracks wrist landmark velocity over five consecutive frames. Only deliberate swipes moving faster than 400 pixels per second trigger a slide transition, followed by an immediate 500-millisecond lock to prevent double-skipping.&quot;</p></blockquote>',8)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
